#!/usr/bin/env python3
# Generated by morzsa via A2A Mesh delegation
"""
MCP-bridge katalógus endpoint: idegen MCP-agentek láthatóak legyenek
a dashboardon end-device státusszal.

Ez a modul egy FastAPI router-t biztosít, amely:
  - A regisztrált idegen MCP-agenteket katalógusba gyűjti
  - End-device státusszal (online/offline/degraded) látja el őket
  - Periodikus health-check-et végez rajtuk
  - Dashboard számára JSON endpointeket exposed
  - Új MCP-agentet lehet hozzáadni / eltávolítani

Futtatható önállóan is (demo szerver) vagy importálható router-ként.
"""

import asyncio
import json
import time
import uuid
from dataclasses import dataclass, field, asdict
from enum import Enum
from pathlib import Path
from typing import Dict, List, Optional, Any
from datetime import datetime, timezone

try:
    import httpx
except ImportError:
    httpx = None  # fallback: csak helyi katalógus, no remote probe

try:
    from fastapi import FastAPI, APIRouter, HTTPException, Query
    from fastapi.responses import JSONResponse
    from pydantic import BaseModel, Field
except ImportError:
    FastAPI = None
    APIRouter = None

# ---------------------------------------------------------------------------
# Adatmodellek
# ---------------------------------------------------------------------------

class DeviceStatus(str, Enum):
    ONLINE = "online"
    OFFLINE = "offline"
    DEGRADED = "degraded"
    UNKNOWN = "unknown"


@dataclass
class MCPCapability:
    """Egy MCP-agent által támogatott képesség."""
    name: str
    version: str = "1.0"
    description: str = ""


@dataclass
class MCPAgentEntry:
    """Katalógusbejegyzés egy idegen MCP-agentről."""
    agent_id: str
    name: str
    endpoint_url: str
    protocol: str = "mcp/1.0"
    status: DeviceStatus = DeviceStatus.UNKNOWN
    capabilities: List[MCPCapability] = field(default_factory=list)
    last_seen: float = 0.0
    last_check: float = 0.0
    latency_ms: float = 0.0
    metadata: Dict[str, Any] = field(default_factory=dict)
    auto_discovered: bool = False
    registered_at: float = field(default_factory=lambda: time.time())

    def to_dict(self) -> dict:
        d = asdict(self)
        d["status"] = self.status.value
        d["capabilities"] = [asdict(c) if isinstance(c, MCPCapability) else c for c in self.capabilities]
        return d

    def is_stale(self, max_age_seconds: int = 120) -> bool:
        return (time.time() - self.last_check) > max_age_seconds


# ---------------------------------------------------------------------------
# Pydantic modellek (API request/response)
# ---------------------------------------------------------------------------

if FastAPI is not None:
    class RegisterAgentRequest(BaseModel):
        name: str = Field(..., description="MCP-agent neve")
        endpoint_url: str = Field(..., description="MCP-agent endpoint URL")
        protocol: str = Field("mcp/1.0")
        capabilities: List[Dict[str, str]] = Field(default_factory=list)
        metadata: Dict[str, Any] = Field(default_factory=dict)
        auto_discovered: bool = False


    class AgentResponse(BaseModel):
        agent_id: str
        name: str
        endpoint_url: str
        protocol: str
        status: str
        capabilities: List[Dict[str, str]]
        last_seen: float
        last_check: float
        latency_ms: float
        metadata: Dict[str, Any]
        auto_discovered: bool
        registered_at: float


# ---------------------------------------------------------------------------
# Katalógus manager
# ---------------------------------------------------------------------------

class MCPCatalog:
    """
    Központi katalógus a regisztrált idegen MCP-agentek számára.
    Thread-safe asyncio lock-kal, opcionális persistence JSON fájlba.
    """

    def __init__(self, persistence_path: Optional[Path] = None):
        self._agents: Dict[str, MCPAgentEntry] = {}
        self._lock = asyncio.Lock()
        self._persistence_path = persistence_path
        self._health_task: Optional[asyncio.Task] = None
        self._running = False
        if persistence_path and persistence_path.exists():
            self._load_from_disk()

    # --- persistence ---

    def _load_from_disk(self):
        if not self._persistence_path or not self._persistence_path.exists():
            return
        try:
            raw = json.loads(self._persistence_path.read_text(encoding="utf-8"))
            for entry_data in raw.get("agents", []):
                caps = [MCPCapability(**c) for c in entry_data.pop("capabilities", [])]
                status_val = entry_data.pop("status", "unknown")
                entry = MCPAgentEntry(**entry_data, capabilities=caps)
                entry.status = DeviceStatus(status_val)
                self._agents[entry.agent_id] = entry
        except Exception as e:
            print(f"[MCPCatalog] WARN: persistence load failed: {e}")

    def _save_to_disk(self):
        if not self._persistence_path:
            return
        try:
            data = {"agents": [a.to_dict() for a in self._agents.values()]}
            self._persistence_path.write_text(
                json.dumps(data, indent=2, ensure_ascii=False),
                encoding="utf-8"
            )
        except Exception as e:
            print(f"[MCPCatalog] WARN: persistence save failed: {e}")

    # --- CRUD ---

    async def register(
        self,
        name: str,
        endpoint_url: str,
        protocol: str = "mcp/1.0",
        capabilities: Optional[List[Dict[str, str]]] = None,
        metadata: Optional[Dict[str, Any]] = None,
        auto_discovered: bool = False,
    ) -> MCPAgentEntry:
        async with self._lock:
            # Ha már létezik ugyanazzal az endpoint-tal, update
            existing = None
            for agent in self._agents.values():
                if agent.endpoint_url == endpoint_url:
                    existing = agent
                    break

            if existing:
                existing.name = name
                existing.protocol = protocol
                existing.metadata = metadata or {}
                existing.auto_discovered = auto_discovered
                if capabilities:
                    existing.capabilities = [
                        MCPCapability(
                            name=c.get("name", "unknown"),
                            version=c.get("version", "1.0"),
                            description=c.get("description", ""),
                        )
                        for c in capabilities
                    ]
                entry = existing
            else:
                agent_id = f"mcp-{uuid.uuid4().hex[:12]}"
                caps = []
                if capabilities:
                    caps = [
                        MCPCapability(
                            name=c.get("name", "unknown"),
                            version=c.get("version", "1.0"),
                            description=c.get("description", ""),
                        )
                        for c in capabilities
                    ]
                entry = MCPAgentEntry(
                    agent_id=agent_id,
                    name=name,
                    endpoint_url=endpoint_url,
                    protocol=protocol,
                    capabilities=caps,
                    metadata=metadata or {},
                    auto_discovered=auto_discovered,
                )
                self._agents[agent_id] = entry

            self._save_to_disk()
            return entry

    async def unregister(self, agent_id: str) -> bool:
        async with self._lock:
            if agent_id in self._agents:
                del self._agents[agent_id]
                self._save_to_disk()
                return True
            return False

    async def get(self, agent_id: str) -> Optional[MCPAgentEntry]:
        async with self._lock:
            return self._agents.get(agent_id)

    async def list_all(self) -> List[MCPAgentEntry]:
        async with self._lock:
            return list(self._agents.values())

    async def list_by_status(self, status: DeviceStatus) -> List[MCPAgentEntry]:
        async with self._lock:
            return [a for a in self._agents.values() if a.status == status]

    # --- health check ---

    async def _probe_agent(self, entry: MCPAgentEntry) -> None:
        """Egyetlen agent health-check-je. httpx ha van, különben offline jelölés."""
        start = time.monotonic()
        try:
            if httpx is None:
                entry.status = DeviceStatus.UNKNOWN
                entry.last_check = time.time()
                return

            async with httpx.AsyncClient(timeout=10.0) as client:
                # MCP agents tipikusan /health vagy /info endpointot exposed
                health_url = entry.endpoint_url.rstrip("/") + "/health"
                try:
                    resp = await client.get(health_url)
                    if resp.status_code == 200:
                        entry.status = DeviceStatus.ONLINE
                        entry.last_seen = time.time()
                        # Próbáljuk capabilities-t frissíteni
                        try:
                            body = resp.json()
                            if "capabilities" in body:
                                entry.capabilities = [
                                    MCPCapability(
                                        name=c.get("name", "unknown"),
                                        version=c.get("version", "1.0"),
                                        description=c.get("description", ""),
                                    )
                                    for c in body["capabilities"]
                                ]
                        except Exception:
                            pass
                    elif 400 <= resp.status_code < 500:
                        # Próbáljuk /info endpoint
                        info_url = entry.endpoint_url.rstrip("/") + "/info"
                        resp2 = await client.get(info_url)
                        if resp2.status_code == 200:
                            entry.status = DeviceStatus.ONLINE
                            entry.last_seen = time.time()
                        else:
                            entry.status = DeviceStatus.DEGRADED
                    else:
                        entry.status = DeviceStatus.DEGRADED
                except httpx.ConnectError:
                    entry.status = DeviceStatus.OFFLINE
                except httpx.TimeoutException:
                    entry.status = DeviceStatus.DEGRADED
        except Exception as e:
            entry.status = DeviceStatus.OFFLINE
            entry.metadata["last_error"] = str(e)
        finally:
            entry.latency_ms = round((time.monotonic() - start) * 1000, 2)
            entry.last_check = time.time()

    async def health_check_all(self) -> None:
        """Az összes agent health-check-je párhuzamosan."""
        agents = await self.list_all()
        if not agents:
            return
        tasks = [self._probe_agent(a) for a in agents]
        await asyncio.gather(*tasks, return_exceptions=True)
        async with self._lock:
            self._save_to_disk()

    async def _health_loop(self, interval: int = 60):
        """Periodikus health-check loop."""
        while self._running:
            try:
                await self.health_check_all()
            except Exception as e:
                print(f"[MCPCatalog] health loop error: {e}")
            await asyncio.sleep(interval)

    def start_health_monitor(self, interval: int = 60):
        if self._health_task and not self._health_task.done():
            return
        self._running = True
        self._health_task = asyncio.create_task(self._health_loop(interval))

    async def stop_health_monitor(self):
        self._running = False
        if self._health_task:
            self._health_task.cancel()
            try:
                await self._health_task
            except asyncio.CancelledError:
                pass
            self._health_task = None

    # --- dashboard summary ---

    async def dashboard_summary(self) -> dict:
        agents = await self.list_all()
        status_counts = {s.value: 0 for s in DeviceStatus}
        for a in agents:
            status_counts[a.status.value] += 1
        return {
            "total_agents": len(agents),
            "status_counts": status_counts,
            "online": status_counts["online"],
            "offline": status_counts["offline"],
            "degraded": status_counts["degraded"],
            "unknown": status_counts["unknown"],
            "timestamp": datetime.now(timezone.utc).isoformat(),
            "agents": [a.to_dict() for a in agents],
        }


# ---------------------------------------------------------------------------
# FastAPI router
# ---------------------------------------------------------------------------

def create_router(catalog: MCPCatalog) -> "APIRouter":
    """Létrehozza a FastAPI router-t a katalógus endpointokkal."""
    if APIRouter is None:
        raise RuntimeError("FastAPI not installed. Install with: pip install fastapi uvicorn")

    router = APIRouter(prefix="/mcp-bridge", tags=["mcp-bridge-catalog"])

    @router.get("/catalog", response_class=JSONResponse)
    async def get_catalog():
        """Összes regisztrált MCP-agent listázása (dashboard számára)."""
        agents = await catalog.list_all()
        return {
            "agents": [a.to_dict() for a in agents],
            "count": len(agents),
        }

    @router.get("/catalog/{agent_id}", response_class=JSONResponse)
    async def get_agent(agent_id: str):
        """Egyetlen MCP-agent részletei."""
        agent = await catalog.get(agent_id)
        if not agent:
            raise HTTPException(status_code=404, detail=f"Agent {agent_id} not found")
        return agent.to_dict()

    @router.post("/catalog/register", response_class=JSONResponse)
    async def register_agent(req: RegisterAgentRequest):
        """Új MCP-agent regisztrálása a katalógusba."""
        entry = await catalog.register(
            name=req.name,
            endpoint_url=req.endpoint_url,
            protocol=req.protocol,
            capabilities=req.capabilities,
            metadata=req.metadata,
            auto_discovered=req.auto_discovered,
        )
        # Azonnali probe
        await catalog._probe_agent(entry)
        return entry.to_dict()

    @router.delete("/catalog/{agent_id}", response_class=JSONResponse)
    async def unregister_agent(agent_id: str):
        """MCP-agent eltávolítása a katalógusból."""
        ok = await catalog.unregister(agent_id)
        if not ok:
            raise HTTPException(status_code=404, detail=f"Agent {agent_id} not found")
        return {"deleted": True, "agent_id": agent_id}

    @router.get("/dashboard", response_class=JSONResponse)
    async def dashboard():
        """Dashboard summary: státuszok, counts, agent lista end-device view-ként."""
        return await catalog.dashboard_summary()

    @router.get("/end-devices", response_class=JSONResponse)
    async def end_devices(status: Optional[str] = Query(None)):
        """
        End-device státusz nézet: a dashboard ezt használja,
        hogy az idegen MCP-agenteket end-device-ként jelenítse meg.
        """
        agents = await catalog.list_all()
        if status:
            try:
                desired = DeviceStatus(status)
                agents = [a for a in agents if a.status == desired]
            except ValueError:
                raise HTTPException(status_code=400, detail=f"Invalid status: {status}")

        devices = []
        for a in agents:
            devices.append({
                "device_id": a.agent_id,
                "device_name": a.name,
                "device_type": "mcp_agent",
                "endpoint": a.endpoint_url,
                "protocol": a.protocol,
                "status": a.status.value,
                "latency_ms": a.latency_ms,
                "last_seen": a.last_seen,
                "last_check": a.last_check,
                "capabilities": [c.name for c in a.capabilities],
                "metadata": a.metadata,
                "auto_discovered": a.auto_discovered,
                "registered_at": a.registered_at,
            })
        return {
            "devices": devices,
            "count": len(devices),
            "source": "mcp-bridge-catalog",
        }

    @router.post("/health-check", response_class=JSONResponse)
    async def trigger_health_check():
        """Manuális health-check trigger az összes agentre."""
        await catalog.health_check_all()
        return await catalog.dashboard_summary()

    return router


