async def seed_from_config(catalog: MCPCatalog, config: dict) -> int:
    """Seedeli a katalógust egy konfig dict-ből. Visszaadja a hozzáadottak számát."""
    count = 0
    for agent_cfg in config.get("agents", []):
        await catalog.register(
            name=agent_cfg["name"],
            endpoint_url=agent_cfg["endpoint_url"],
            protocol=agent_cfg.get("protocol", "mcp/1.0"),
            capabilities=agent_cfg.get("capabilities", []),
            metadata=agent_cfg.get("metadata", {}),
            auto_discovered=True,
        )
        count += 1
    return count


# ---------------------------------------------------------------------------
# CLI / standalone szerver
# ---------------------------------------------------------------------------

def create_app(catalog: Optional[MCPCatalog] = None) -> "FastAPI":
    """Létrehozza a teljes FastAPI app-ot a router-rel."""
    if FastAPI is None:
        raise RuntimeError("FastAPI not installed. Install with: pip install fastapi uvicorn httpx")

    if catalog is None:
        catalog = MCPCatalog(
            persistence_path=Path("mcp_catalog_state.json")
        )

    app = FastAPI(
        title="A2A Mesh — MCP Bridge Catalog",
        description="Idegen MCP-agentek katalógusa end-device státusszal a dashboard számára.",
        version="1.0.0",
    )

    router = create_router(catalog)
    app.include_router(router)

    # Store catalog on app state
    app.state.mcp_catalog = catalog

    @app.on_event("startup")
    async def startup():
        # Seed ha üres
        agents = await catalog.list_all()
        if not agents:
            n = await seed_from_config(catalog, DEFAULT_SEED_CONFIG)
            print(f"[MCP-Bridge] Seeded {n} agents from default config")
        catalog.start_health_monitor(interval=60)
        print("[MCP-Bridge] Health monitor started (interval=60s)")

    @app.on_event("shutdown")
    async def shutdown():
        await catalog.stop_health_monitor()
        print("[MCP-Bridge] Health monitor stopped")

    return app


def main():
    """Standalone szerver indítás."""
    import argparse

    parser = argparse.ArgumentParser(
        description="MCP-bridge katalógus endpoint szerver"
    )
    parser.add_argument("--host", default="0.0.0.0", help="Bind host")
    parser.add_argument("--port", type=int, default=8100, help="Bind port")
    parser.add_argument("--state", default="mcp_catalog_state.json",
                        help="Persistence JSON fájl útvonala")
    parser.add_argument("--no-seed", action="store_true",
                        help="Ne seedeljen default agenteket")
    parser.add_argument("--health-interval", type=int, default=60,
                        help="Health-check interval másodpercben")
    args = parser.parse_args()

    if FastAPI is None:
        print("ERROR: FastAPI nincs telepítve.")
        print("Telepítsd: pip install fastapi uvicorn httpx")
        return

    catalog = MCPCatalog(persistence_path=Path(args.state))

    # Ha nem üres a persistence, nem seedelünk
    if not args.no_seed:
        existing = asyncio.run(catalog.list_all())
        if not existing:
            n = asyncio.run(seed_from_config(catalog, DEFAULT_SEED_CONFIG))
            print(f"[MCP-Bridge] Seeded {n} agents from default config")

    app = create_app(catalog)

    # Override health interval
    @app.on_event("startup")
    async def _override_health():
        await catalog.stop_health_monitor()
        catalog.start_health_monitor(interval=args.health_interval)

    import uvicorn
    print(f"[MCP-Bridge] Starting server on {args.host}:{args.port}")
    print(f"[MCP-Bridge] State file: {args.state}")
    print(f"[MCP-Bridge] Health interval: {args.health_interval}s")
    print(f"[MCP-Bridge] Endpoints:")
    print(f"  GET  /mcp-bridge/catalog        — összes agent")
    print(f"  GET  /mcp-bridge/catalog/{{id}}   — egy agent")
    print(f"  POST /mcp-bridge/catalog/register — új agent")
    print(f"  DEL  /mcp-bridge/catalog/{{id}}   — agent törlés")
    print(f"  GET  /mcp-bridge/dashboard      — dashboard summary")
    print(f"  GET  /mcp-bridge/end-devices    — end-device view")
    print(f"  POST /mcp-bridge/health-check   — manuális probe")
    uvicorn.run(app, host=args.host, port=args.port)


if __name__ == "__main__":
    main()